// 접수 지점이 고정되어 있지 않다.
// 보호자 문자 · 코디네이터 입력 · 치료사 전달이 모두 여기로 수렴한다.
const items = $input.all();
return items.map((item) => {
  const b = item.json.body ?? item.json;
  const text = b.text ?? b.message ?? b.content ?? '';
  return {
    json: {
      text: String(text).trim(),
      submittedBy: b.submittedBy ?? b.role ?? 'unknown', // coordinator | therapist | guardian
      channel: b.channel ?? 'sms',
      receivedAt: new Date().toISOString(),
    },
  };
});

// 모델 응답에서 JSON만 뽑는다. 실패하면 정규식 폴백으로 내려간다.
const THERAPIES = [
  { code: 'PT_BASIC', aliases: ['물리', '물리치료', 'PT', '피티'] },
  { code: 'HYDRO',    aliases: ['수치료', '물속치료', '풀'] },
  { code: 'ROBOT',    aliases: ['로봇', '로봇치료', '보행로봇'] },
  { code: 'EQUIP',    aliases: ['기구', '기구치료'] },
  { code: 'OT_BASIC', aliases: ['작업', '작업치료', 'OT', '오티'] },
  { code: 'COG',      aliases: ['인지', '전산화인지', '인지치료'] },
  { code: 'SI',       aliases: ['감통', '감각통합', '감각치료'] },
  { code: 'SWALLOW',  aliases: ['연하', '삼킴', '연하치료'] },
];

function fallback(text) {
  const mentioned = THERAPIES.filter(t => t.aliases.some(a => text.includes(a))).map(t => t.code);
  const onlyMarker = /만\s*(빼|빠|제외|취소)/.test(text);
  const allMarker  = /(전체|모두|다)\s*(못|안|결석|취소)/.test(text);
  // 유지 표지가 함께 있으면 규칙만으로는 결석 대상을 특정할 수 없다 — 오판 대신 기권 (웹 fallbackParser.ts와 동일)
  const keepMarker = /그대로|[은는]\s*(받|올|갈)/.test(text);
  const dateWord   = (text.match(/(오늘|내일|모레)/) || [])[1] || null;
  const idToken    = (text.match(/C-\d{2}/) || [])[0] || null;
  let scope = null, cancelled = null;
  if (allMarker && mentioned.length === 0) scope = 'all';
  else if (onlyMarker && mentioned.length > 0 && !keepMarker) { scope = 'partial'; cancelled = mentioned; }
  return {
    fields: { subjectToken: idToken, date: dateWord, scope, cancelledTherapies: cancelled, reason: null },
    source: 'fallback',
  };
}

const anon = $('익명화 전처리 (Python)').first().json;
const out = [];
for (const item of $input.all()) {
  let parsed = null;
  try {
    const raw = String(item.json.response ?? '').replace(/```json|```/g, '').trim();
    const j = JSON.parse(raw);
    if (j && j.fields) parsed = { fields: j.fields, confidence: j.confidence ?? {}, source: 'ai' };
  } catch (e) { parsed = null; }
  if (!parsed) parsed = fallback(anon.anonymizedText);
  out.push({ json: { ...parsed, anonymizedText: anon.anonymizedText } });
}
return out;

// 매칭 규칙 엔진 — AI를 호출하지 않는다. 전부 결정론적이다.
// 이 노드는 토큰만 다룬다. 실명은 등장하지 않는다.
// 웹 프로토타입 lib/matcher.ts 와 동일한 규칙을 사용한다.

const OUTPATIENT_SESSIONS = [
  { time: '14:00', therapy: 'PT_BASIC', staff: 'PT-03' },
  { time: '14:30', therapy: 'HYDRO',    staff: 'PT-04' },
  { time: '15:00', therapy: 'OT_BASIC', staff: 'OT-07' },
  { time: '15:30', therapy: 'SI',       staff: 'OT-11' },
];

const extract = $('추출 결과 파싱').first().json;
const waitRows = $('대기 명단 파싱').all().map(i => i.json);

// 1) 결석으로 비는 회기 확정
let openSlots = [];
if (extract.fields.scope === 'all') {
  openSlots = OUTPATIENT_SESSIONS;
} else if (extract.fields.scope === 'partial' && Array.isArray(extract.fields.cancelledTherapies)) {
  const set = new Set(extract.fields.cancelledTherapies);
  openSlots = OUTPATIENT_SESSIONS.filter(s => set.has(s.therapy));
}

// 2) 회기별 후보 매칭
const results = openSlots.map((slot) => {
  const passed = [];
  const excluded = [];
  for (const w of waitRows) {
    if (w.therapy !== slot.therapy) continue;
    const remaining = Number(w.remaining);
    if (!(remaining > 0)) { excluded.push({ token: w.child_id, cause: '잔여 기회 없음' }); continue; }
    const busy = String(w.busy_times ?? '').split('|').map(s => s.trim()).filter(Boolean);
    if (busy.includes(slot.time)) { excluded.push({ token: w.child_id, cause: slot.time + ' 다른 일정' }); continue; }
    passed.push({ ...w, remaining, waiting_days: Number(w.waiting_days) });
  }
  // 우선순위: 잔여 기회 적은 순 → 대기 긴 순 → id 오름차순 (재현성 보장)
  // 수익성이나 배정 용이성이 아니라 형평 기준으로 정렬한다.
  passed.sort((a, b) =>
    (a.remaining - b.remaining) ||
    (b.waiting_days - a.waiting_days) ||
    String(a.child_id).localeCompare(String(b.child_id))
  );
  return { ...slot, candidates: passed.slice(0, 3), excluded };
});

return [{ json: {
  scope: extract.fields.scope,
  source: extract.source,
  openSlotCount: openSlots.length,
  slots: results,
  hasCandidate: results.some(r => r.candidates.length > 0),
} }];

// 승인 큐로 보낼 안내문 초안. 발송이 아니라 제안이다.
const d = $input.first().json;
const lines = d.resolved.map(r =>
  '· ' + r.time + ' ' + r.therapyName + ' (' + r.staff + ') → '
  + r.displayName + ' / 잔여 ' + r.remaining + '회 · 대기 ' + r.waitingDays + '일'
);
const message = [
  '[보강 제안]',
  '결석으로 아래 회기가 비었습니다. 배정 가능하신지 회신 부탁드립니다.',
  '',
  ...lines,
  '',
  '※ 확정 아님 · 코디네이터 승인 후 배정됩니다.',
].join('\n');
return [{ json: { message, slotCount: d.slotCount, source: d.source, needsApproval: true } }];
